create or replace function public.admin_list_review_reports(p_status text default 'pending') returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ begin if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and is_admin=true) then raise exception 'ADMIN_REQUIRED'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at asc) from (select rr.id,rr.review_id,rr.reporter_id,rr.reason,rr.details,rr.created_at,rr.status,rr.resolved_by,rr.resolved_at,r.location_id,r.user_id as review_author,r.stars,r.cleanliness_pct,r.comment,r.status as review_status,l.name as location_name from public.review_reports rr join public.reviews r on r.id=rr.review_id join public.locations l on l.id=r.location_id where (p_status is null or p_status='' or rr.status=p_status)) x),'[]'::jsonb); end; $function$;
create or replace function public.admin_resolve_review_report(p_report_id uuid,p_resolution text,p_reason text,p_review_status public.review_status default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_uid uuid:=auth.uid(); v_report public.review_reports%rowtype; v_review public.reviews%rowtype; v_resolution text:=lower(trim(p_resolution)); v_reason text:=nullif(trim(p_reason),''); begin if v_uid is null or not exists(select 1 from public.profiles where id=v_uid and is_admin=true) then raise exception 'ADMIN_REQUIRED'; end if; if v_reason is null then raise exception 'RESOLUTION_REASON_REQUIRED'; end if; if v_resolution not in ('dismiss','hide','restore') then raise exception 'INVALID_REPORT_RESOLUTION'; end if; select * into v_report from public.review_reports where id=p_report_id for update; if not found then raise exception 'REPORT_NOT_FOUND'; end if; if v_report.status<>'pending' then raise exception 'REPORT_ALREADY_RESOLVED'; end if; select * into v_review from public.reviews where id=v_report.review_id for update; if not found then raise exception 'REVIEW_NOT_FOUND'; end if; if v_resolution='hide' then perform public.moderate_review(v_review.id,'hidden'::public.review_status,v_reason); elsif v_resolution='restore' then perform public.moderate_review(v_review.id,'published'::public.review_status,v_reason); elsif p_review_status is not null then perform public.moderate_review(v_review.id,p_review_status,v_reason); end if; update public.review_reports set status=case when v_resolution='dismiss' then 'rejected' else 'approved' end,resolved_by=v_uid,resolved_at=now() where id=p_report_id returning * into v_report; return jsonb_build_object('report',to_jsonb(v_report),'review_id',v_review.id,'resolution',v_resolution); end; $function$;
comment on function public.admin_list_review_reports(text) is 'Owner/admin moderation queue for user-reported reviews.';
comment on function public.admin_resolve_review_report(uuid,text,text,review_status) is 'Owner/admin resolution of a review report; hide/restore transitions use canonical review moderation and preserve provenance.';
revoke execute on function public.admin_list_review_reports(text) from anon,authenticated;
grant execute on function public.admin_list_review_reports(text) to authenticated;
revoke execute on function public.admin_resolve_review_report(uuid,text,text,review_status) from anon,authenticated;
grant execute on function public.admin_resolve_review_report(uuid,text,text,review_status) to authenticated;
